/* Start here entry for chi-square-tests (demos/lib/starthere/chi-square-tests.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"A die is loaded so that a six comes up a quarter of the time. Will a chi square test of 60 rolls catch it?","q_es":"Un dado está cargado para que el seis salga una cuarta parte de las veces. ¿Una prueba ji cuadrada de 60 tiros lo detectará?","setup":"","do":"Read the table of observed and expected counts, <b>Chi square χ²</b> and the <b>p value</b>. Then set <b>Rolls</b> to 600 and read them again.","do_es":"Lee la tabla de conteos observados y esperados, <b>Ji cuadrada χ²</b> y el <b>Valor p</b>. Luego pon <b>Tiros</b> en 600 y vuelve a leerlos.","see":"With 60 rolls there are 16 sixes against 10 expected: χ² = 5.2000 and p = 0.3920, so do not reject H₀. With 600 rolls, 163 sixes against 100: χ² = 51.5600 and p = 6.6 × 10⁻¹⁰. The die was loaded all along. Not rejecting H₀ does not show the die is fair, only that 60 rolls are too few to tell.","see_es":"Con 60 tiros hay 16 seises contra 10 esperados: χ² = 5.2000 y p = 0.3920, así que no se rechaza H₀. Con 600 tiros, 163 seises contra 100: χ² = 51.5600 y p = 6.6 × 10⁻¹⁰. El dado estuvo cargado todo el tiempo. No rechazar H₀ no demuestra que el dado sea justo, solo que 60 tiros son muy pocos para saberlo.","explore":[{"setup":"set=speed~20!rolls~600!p6~0.2!alpha~0.05!labBlind~0","do":"A die only slightly loaded: <b>Chance of a six</b> 0.20, against 1/6 = 0.1667 for a fair die, rolled 600 times. Read χ² and the <b>p value</b>, then set <b>Rolls</b> to 60.","do_es":"Un dado apenas cargado: <b>Probabilidad de un seis</b> 0.20, contra 1/6 = 0.1667 para un dado justo, con 600 tiros. Lee χ² y el <b>Valor p</b>, luego pon <b>Tiros</b> en 60.","see":"At 600 rolls, 133 sixes against 100: χ² = 16.4800 and p = 0.0056, significant. At 60 rolls, 11 sixes against 10: χ² = 0.4000 and p = 0.9953. With enough rolls even a small loading is significant: a small p says the die is not fair, not that it is badly loaded.","see_es":"Con 600 tiros, 133 seises contra 100: χ² = 16.4800 y p = 0.0056, significativa. Con 60 tiros, 11 seises contra 10: χ² = 0.4000 y p = 0.9953. Con suficientes tiros, hasta una carga pequeña es significativa: una p pequeña dice que el dado no es justo, no que esté muy cargado."},{"setup":"set=speed~20!nInt~200!rate~25!dead~0.02!alpha~0.05!labBlind~0!g%3Apresets~dead","do":"<b>A counter with dead time (simulated)</b>: 25 arrivals a second, counted in 200 intervals of 1 s, and the counter is blind for 20 ms after each count. Read <b>Mean count per interval</b>, χ² and the <b>p value</b>, then set <b>Dead time</b> to none.","do_es":"<b>Un contador con tiempo muerto (simulado)</b>: 25 llegadas por segundo, contadas en 200 intervalos de 1 s, y el contador queda ciego 20 ms después de cada conteo. Lee <b>Conteo medio por intervalo</b>, χ² y el <b>Valor p</b>, luego pon <b>Tiempo muerto</b> en ninguno.","see":"With dead time the counter records 16.815 counts a second, missing about a third, and the counts are too even for a Poisson distribution: χ² = 38.4457 with df = 13, p = 0.0002. With none it records 25.230, and χ² = 15.8613 with df = 16, p = 0.4627: Poisson fits.","see_es":"Con tiempo muerto el contador registra 16.815 conteos por segundo, pierde más o menos un tercio, y los conteos son demasiado parejos para una distribución de Poisson: χ² = 38.4457 con gl = 13, p = 0.0002. Sin tiempo muerto registra 25.230, y χ² = 15.8613 con gl = 16, p = 0.4627: Poisson se ajusta."}]});
